class Counter {
  static int classCount = 0;  // Shared by all
  int instanceCount = 0;     // Unique to each
}

Counter c1 = new Counter();
Counter c2 = new Counter();
// classCount is shared between c1 and c2
// Each has their own instanceCount

c1.instanceCount++;  // Only c1's count changes
Counter.classCount++;  // Affects ALL Counters
// c1.classCount and c2.classCount both increment

