problem.solution:
class Circle {
  final static double PI = 3.14159;
  double radius;

  Circle(double radius) {
    this.radius = radius;
  }

  static double calculateArea(double radius) {
    return PI * radius * radius;
  }

  double getCircumference() {
    return 2 * PI * radius;
  }
}
